CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_alerta_panel` AS
select `c`.`id_alert` AS `id_alert`,`c`.`inicio` AS `inicio`,`c`.`horas_abierta` AS `horas_abierta`,`c`.`severidad` AS `severidad`,`c`.`texto` AS `texto`,`c`.`expresion` AS `expresion`,`c`.`que_mide` AS `que_mide`,`c`.`concepto` AS `concepto`,`c`.`unidad` AS `unidad`,`c`.`clase` AS `clase`,`c`.`dispositivo` AS `dispositivo`,`c`.`ip` AS `ip`,`c`.`instancia` AS `instancia`,`c`.`rol` AS `rol`,`c`.`rol_nombre` AS `rol_nombre`,`c`.`rol_tipo` AS `rol_tipo`,`c`.`criticidad` AS `criticidad`,`c`.`es_primaria` AS `es_primaria`,`c`.`veces_30d` AS `veces_30d`,`c`.`dur_media_min` AS `dur_media_min`,`c`.`otras_del_equipo` AS `otras_del_equipo`,`c`.`otras_del_rol` AS `otras_del_rol`,`c`.`simultaneas` AS `simultaneas`,(case when (isnull(`c`.`veces_30d`) or (`c`.`veces_30d` <= 1)) then 'primera vez en 30 dias' when ((`c`.`dur_media_min` < 15) and (`c`.`veces_30d` > 20)) then concat('PARPADEO RECURRENTE: ',`c`.`veces_30d`,' veces, media ',`c`.`dur_media_min`,' min') when (`c`.`dur_media_min` > 1440) then concat('CAIDAS LARGAS: media ',round((`c`.`dur_media_min` / 1440),1),' dias') when (`c`.`veces_30d` > 10) then concat('RECURRENTE: ',`c`.`veces_30d`,' veces en 30 dias') else concat('ocasional: ',`c`.`veces_30d`,' veces en 30 dias') end) AS `patron`,(case when (`c`.`horas_abierta` > 720) then 'ABIERTA HACE MAS DE 30 DIAS' when (`c`.`horas_abierta` > 168) then 'abierta hace mas de 7 dias' end) AS `antiguedad` from `v_alerta_contexto` `c` order by isnull(`c`.`criticidad`),`c`.`criticidad`,`c`.`inicio`;
